'use client';

import { IconPlaceholder } from '@/components/icon-placeholder';
import { IndentPlugin, useEditor } from 'platejs/react';
import * as React from 'react';

import { ToolbarButton } from '@/registry/components/editor/toolbar';

export function IndentToolbarButton(
  props: React.ComponentProps<typeof ToolbarButton>
) {
  const { update } = useEditor().plugin(IndentPlugin);

  return (
    <ToolbarButton
      {...props}
      tooltip="Indent"
      onClick={() => {
        update.increase();
      }}
    >
      <IconPlaceholder lucide="IndentIcon" tabler="IconIndentIncrease" hugeicons="TextIndentMoreIcon" phosphor="TextIndentIcon" remixicon="RiIndentIncrease" className="[&:dir(rtl)]:-scale-x-100" />
    </ToolbarButton>
  );
}

export function OutdentToolbarButton(
  props: React.ComponentProps<typeof ToolbarButton>
) {
  const { update } = useEditor().plugin(IndentPlugin);

  return (
    <ToolbarButton
      {...props}
      tooltip="Outdent"
      onClick={() => {
        update.decrease();
      }}
    >
      <IconPlaceholder lucide="OutdentIcon" tabler="IconIndentDecrease" hugeicons="TextIndentLessIcon" phosphor="TextOutdentIcon" remixicon="RiIndentDecrease" className="[&:dir(rtl)]:-scale-x-100" />
    </ToolbarButton>
  );
}
